func (this *Widget) FixMnemonicStringSpacesRemoveAppended(string_ string, spaces bool, removeAppended bool) []uint16 {
	var buffer []uint16 = make([]uint16, jrt.StringLength(string_)+1)
	jrt.GetChars(string_, 0, jrt.StringLength(string_), buffer, 0)
	var i int32 = 0
	var j int32 = 0
	for i < int32(len(buffer)) {
		if int32(buffer[i]) == int32('&') {
			if i+1 < int32(len(buffer)) && int32(buffer[i+1]) == int32('&') {
				t57 := j
				j++
				if spaces {
					buffer[t57] = ' '
				} else {
					buffer[t57] = buffer[i]
				}
				i++
			}
			i++
		} else {
			if int32(buffer[i]) == int32('(') && removeAppended && i+4 == jrt.StringLength(string_) && int32(buffer[i+1]) == int32('&') && int32(buffer[i+3]) == int32(')') {
				if spaces {
					t58 := j
					j++
					buffer[t58] = ' '
				}
				i += 4
			} else {
				t59 := j
				j++
				t60 := i
				i++
				buffer[t59] = buffer[t60]
			}
		}
	}
	for j < int32(len(buffer)) {
		t61 := j
		j++
		buffer[t61] = uint16(0)
	}
	return buffer
}

