func (this *Widget) SetInputState(eventLike EventLike, type_ int32) bool {
	var event *Event
	if eventLike != nil {
		event = eventLike.AsEvent()
	}
	_ = event
	if int32(win32.OSGetKeyState(win32.OSVK_MENU)) < 0 {
		event.StateMask |= ALT
	}
	if int32(win32.OSGetKeyState(win32.OSVK_SHIFT)) < 0 {
		event.StateMask |= SHIFT
	}
	if int32(win32.OSGetKeyState(win32.OSVK_CONTROL)) < 0 {
		event.StateMask |= CONTROL
	}
	if int32(win32.OSGetKeyState(win32.OSVK_LBUTTON)) < 0 {
		event.StateMask |= BUTTON1
	}
	if int32(win32.OSGetKeyState(win32.OSVK_MBUTTON)) < 0 {
		event.StateMask |= BUTTON2
	}
	if int32(win32.OSGetKeyState(win32.OSVK_RBUTTON)) < 0 {
		event.StateMask |= BUTTON3
	}
	if this.display.xMouse {
		if int32(win32.OSGetKeyState(win32.OSVK_XBUTTON1)) < 0 {
			event.StateMask |= BUTTON4
		}
		if int32(win32.OSGetKeyState(win32.OSVK_XBUTTON2)) < 0 {
			event.StateMask |= BUTTON5
		}
	}
	switch type_ {
	case MouseDown, MouseDoubleClick:
		if event.Button == 1 {
			event.StateMask &= ^BUTTON1
		}
		if event.Button == 2 {
			event.StateMask &= ^BUTTON2
		}
		if event.Button == 3 {
			event.StateMask &= ^BUTTON3
		}
		if event.Button == 4 {
			event.StateMask &= ^BUTTON4
		}
		if event.Button == 5 {
			event.StateMask &= ^BUTTON5
		}
		break
	case MouseUp:
		if event.Button == 1 {
			event.StateMask |= BUTTON1
		}
		if event.Button == 2 {
			event.StateMask |= BUTTON2
		}
		if event.Button == 3 {
			event.StateMask |= BUTTON3
		}
		if event.Button == 4 {
			event.StateMask |= BUTTON4
		}
		if event.Button == 5 {
			event.StateMask |= BUTTON5
		}
		break
	case KeyDown, Traverse:
		if event.KeyCode == ALT {
			event.StateMask &= ^ALT
		}
		if event.KeyCode == SHIFT {
			event.StateMask &= ^SHIFT
		}
		if event.KeyCode == CONTROL {
			event.StateMask &= ^CONTROL
		}
		break
	case KeyUp:
		if event.KeyCode == ALT {
			event.StateMask |= ALT
		}
		if event.KeyCode == SHIFT {
			event.StateMask |= SHIFT
		}
		if event.KeyCode == CONTROL {
			event.StateMask |= CONTROL
		}
		break
	}
	return true
}

func (this *Widget) SetKeyState(eventLike EventLike, type_ int32, wParam int64, lParam int64) bool {
	var event *Event
	if eventLike != nil {
		event = eventLike.AsEvent()
	}
	_ = event
	switch this.display.lastAscii {
	case int32(DEL):
		if this.display.lastKey == int32(BS) {
			this.display.lastAscii = int32(BS)
		}
		break
	case int32(LF):
		if this.display.lastKey == int32(CR) {
			this.display.lastAscii = int32(CR)
		}
		break
	}
	if this.display.lastKey == int32(CR) && this.display.lastAscii == int32(CR) {
		if (lParam & 0x1000000) != 0 {
			this.display.lastKey = KEYPAD_CR
		}
	}
	this.SetLocationMask(event, type_, wParam, lParam)
	if this.display.lastVirtual {
		if this.display.lastKey == win32.OSVK_DELETE {
			this.display.lastAscii = 0x7F
		}
		if this.display.lastKey == win32.OSVK_CANCEL {
			this.display.lastAscii = 0x0
		}
		event.KeyCode = DisplayTranslateKey(this.display.lastKey)
	} else {
		event.KeyCode = this.display.lastKey
	}
	event.Character = uint16(this.display.lastAscii)
	if event.KeyCode == 0 && int32(event.Character) == 0 {
		return false
	}
	return this.SetInputState(event, type_)
}

func (this *Widget) SetLocationMask(eventLike EventLike, type_ int32, wParam int64, lParam int64) int32 {
	var event *Event
	if eventLike != nil {
		event = eventLike.AsEvent()
	}
	_ = event
	var location int32 = NONE
	if this.display.lastVirtual {
		switch this.display.lastKey {
		case win32.OSVK_SHIFT:
			if int32(win32.OSGetKeyState(win32.OSVK_LSHIFT)) < 0 {
				location = LEFT
			}
			if int32(win32.OSGetKeyState(win32.OSVK_RSHIFT)) < 0 {
				location = RIGHT
			}
			break
		case win32.OSVK_NUMLOCK:
			location = KEYPAD
			break
		case win32.OSVK_CONTROL, win32.OSVK_MENU:
			if (lParam & 0x1000000) == 0 {
				location = LEFT
			} else {
				location = RIGHT
			}
			break
		case win32.OSVK_INSERT, win32.OSVK_DELETE, win32.OSVK_HOME, win32.OSVK_END, win32.OSVK_PRIOR, win32.OSVK_NEXT, win32.OSVK_UP, win32.OSVK_DOWN, win32.OSVK_LEFT, win32.OSVK_RIGHT:
			if (lParam & 0x1000000) == 0 {
				location = KEYPAD
			}
			break
		}
		if this.display.NumpadKey(this.display.lastKey) != 0 {
			location = KEYPAD
		}
	} else {
		if this.display.lastKey == KEYPAD_CR {
			location = KEYPAD
		}
	}
	event.KeyLocation = location
	return location
}

