func (this *Widget) ShowMenuXYDetail(x int32, y int32, detail int32) bool {
	var event *Event = NewEvent()
	var mappedLocation *Point = this.GetDisplay().TranslateFromDisplayCoordinates(NewPoint(x, y))
	event.SetLocation(mappedLocation.X, mappedLocation.Y)
	event.Detail = detail
	if event.Detail == MENU_KEYBOARD {
		this.impl.updateMenuLocation_(event)
	}
	this.SendEventEventTypeEvent(MenuDetect, event)
	if this.IsDisposed() {
		return false
	}
	if !event.Doit {
		return true
	}
	var menu *Menu = this.impl.getMenu_()
	if menu != (nil) && !menu.IsDisposed() {
		var locInPixels *Point = Win32DPIUtilsPointToPixelAsLocationPointZoom(event.GetLocation(), this.impl.getAutoscalingZoom_())
		if x != locInPixels.X || y != locInPixels.Y {
			menu.SetLocationLocation(event.GetLocation())
		}
		menu.SetVisible(true)
		return true
	}
	return false
}

